package com.hospital.smartqueue.doctor.scheduling.application; import com.hospital.smartqueue.common.domain.*; import com.hospital.smartqueue.doctor.scheduling.api.LeaveRequest; import com.hospital.smartqueue.doctor.scheduling.domain.DoctorLeave; import com.hospital.smartqueue.doctor.scheduling.infrastructure.DoctorLeaveRepository; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DoctorLeaveService { private final SchedulingAccessContext access; private final DoctorLeaveRepository leaves; public DoctorLeaveService(SchedulingAccessContext a,DoctorLeaveRepository l){access=a;leaves=l;} @Transactional public UUID add(UUID h,UUID b,UUID d,LeaveRequest r){access.requireManage(h,b,d);if(r.endDate().isBefore(r.startDate()))throw new DomainException("VALIDATION_ERROR","Invalid leave range");if(!leaves.findOverlapping(d,b,r.startDate(),r.endDate()).isEmpty())throw new ConflictException("Leave overlaps existing leave");return leaves.save(new DoctorLeave(d,b,r.startDate(),r.endDate())).getId();}}
